func (c *Client) internalConnLost(err error) {
	close(c.stop)
	c.conn.Close()
	c.workers.Wait()
	if c.IsConnected() {
		go c.options.OnConnectionLost(c err)
		if c.options.AutoReconnect {
			go c.reconnect()
		} else {
			c.setConnected(false)
		}
	}
}

